import org.jooq.DSLContext;
import org.springframework.stereotype.Repository;
import org.springframework.transaction.annotation.Transactional;

import java.util.stream.Stream;

import static ai.unifiedprocess.demo.petclinic.database.Tables.SPECIALTIES;
import static ai.unifiedprocess.demo.petclinic.database.Tables.VETS;
import static ai.unifiedprocess.demo.petclinic.database.Tables.VET_SPECIALTIES;
import static org.jooq.Records.mapping;
import static org.jooq.impl.DSL.multiset;
import static org.jooq.impl.DSL.select;

/**
 * Read access to the clinic's veterinarians, for UC-002 View Veterinarians.
 *
 * <p>Veterinarians are ordered by id, the order the clinic's reference data was
 * entered in, so that windows of the list never overlap. Their specialties are
 * ordered by name (GR-003) and fetched in the same statement as the veterinarian
 * (a {@code multiset}), so the grid costs one query per window, not one per row.
 */
@Repository
@Transactional(readOnly = true)
public class VetRepository {

    private final DSLContext dsl;

    public VetRepository(DSLContext dsl) {
        this.dsl = dsl;
    }

    /**
     * One window of the veterinarian list, for the lazily loaded grid (BR-001).
     */
    public Stream<Vet> findPage(int offset, int limit) {
        return dsl.select(
                        VETS.ID,
                        VETS.FIRST_NAME,
                        VETS.LAST_NAME,
                        multiset(
                                select(SPECIALTIES.NAME)
                                        .from(VET_SPECIALTIES)
                                        .join(SPECIALTIES).on(SPECIALTIES.ID.eq(VET_SPECIALTIES.SPECIALTY_ID))
                                        .where(VET_SPECIALTIES.VET_ID.eq(VETS.ID))
                                        .orderBy(SPECIALTIES.NAME))
                                .convertFrom(specialties -> specialties.map(mapping(Specialty::new))))
                .from(VETS)
                .orderBy(VETS.ID)
                .limit(limit)
                .offset(offset)
                .fetch(mapping(Vet::new))
                .stream();
    }

    /**
     * The number of veterinarians on record, which sizes the lazily loaded grid.
     */
    public int count() {
        return dsl.fetchCount(VETS);
    }
}
