+package ai.unifiedprocess.petclinic.vet.ui;
+
+import ai.unifiedprocess.petclinic.PetClinicTestBase;
+import ai.unifiedprocess.petclinic.UseCase;
+import ai.unifiedprocess.petclinic.vet.domain.Vet;
+import ai.unifiedprocess.petclinic.vet.domain.VetRepository;
+import ai.unifiedprocess.petclinic.welcome.ui.WelcomeView;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.grid.GridTester;
+import com.vaadin.flow.component.sidenav.SideNav;
+import com.vaadin.flow.component.sidenav.SideNavTester;
+import org.jooq.DSLContext;
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Autowired;
+
+import java.util.List;
+
+import static ai.unifiedprocess.demo.petclinic.database.Tables.VETS;
+import static ai.unifiedprocess.demo.petclinic.database.Tables.VET_SPECIALTIES;
+import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
+import static org.junit.jupiter.api.Assertions.assertEquals;
+
+/**
+ * UC-002: View Veterinarians.
+ *
+ * Seed order (V2__seed_reference_data.sql): James Carter (no specialty), Helen
+ * Leary (radiology), Linda Douglas (surgery, dentistry), Rafael Ortega
+ * (surgery), Henry Stevens (radiology), Sharon Jenkins (no specialty).
+ */
+class UC002ViewVeterinariansTest extends PetClinicTestBase {
+
+    @Autowired
+    private VetRepository vetRepository;
+
+    @Autowired
+    private DSLContext dsl;
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-003")
+    void veterinariansViewRendersWithoutAuthentication() {
+        assertDoesNotThrow(() -> navigate(VeterinariansView.class),
+                "Expected the veterinarians view to render for an anonymous visitor");
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void visitorOpensVeterinariansFromNavigationMenu() {
+        navigate(WelcomeView.class);
+        SideNavTester<SideNav> sideNav = test(assertDoesNotThrow(() -> find(SideNav.class).single(),
+                "Expected the main navigation menu"));
+
+        sideNav.clickItem("Veterinarians");
+
+        assertEquals("vets", UI.getCurrent().getInternals().getActiveViewLocation().getPath());
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void gridShowsFirstNameLastNameAndSpecialtiesOfEachVeterinarian() {
+        navigate(VeterinariansView.class);
+
+        GridTester<Grid<Vet>, Vet> grid = veterinariansGrid();
+
+        assertEquals(6, grid.size(), "Expected all six seeded veterinarians");
+        assertEquals("Helen", grid.getCellText(1, 0));
+        assertEquals("Leary", grid.getCellText(1, 1));
+        assertEquals("radiology", grid.getCellText(1, 2));
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void veterinarianWithoutSpecialtyShowsNone() {
+        navigate(VeterinariansView.class);
+
+        assertEquals("none", veterinariansGrid().getCellText(0, 2), "Expected James Carter to show 'none'");
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-002")
+    void specialtiesOfVeterinarianAreListedAlphabetically() {
+        navigate(VeterinariansView.class);
+
+        // Linda Douglas holds surgery (id 2) and dentistry (id 3): id order would read "surgery, dentistry".
+        assertEquals("dentistry, surgery", veterinariansGrid().getCellText(2, 2));
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-001")
+    void veterinariansAreServedInWindowsAndTheLastWindowEndsTheList() {
+        navigate(VeterinariansView.class);
+
+        assertEquals(6, vetRepository.count());
+        assertEquals(List.of("Henry", "Sharon"),
+                vetRepository.findPage(4, 2).map(Vet::firstName).toList());
+        assertEquals("Sharon", veterinariansGrid().getCellText(5, 0));
+    }
+
+    @Test
+    @UseCase(id = "UC-002", scenario = "A1: No Veterinarians Registered")
+    void gridRendersWithNoRowsWhenNoVeterinarianIsRecorded() {
+        dsl.deleteFrom(VET_SPECIALTIES).execute();
+        dsl.deleteFrom(VETS).execute();
+
+        navigate(VeterinariansView.class);
+
+        assertEquals(0, veterinariansGrid().size(), "Expected the veterinarians grid to render with no rows");
+    }
+
+    private GridTester<Grid<Vet>, Vet> veterinariansGrid() {
+        Grid<Vet> grid = assertDoesNotThrow(() -> find(Grid.class).single(),
+                "Expected exactly one veterinarians grid");
+        return test(grid);
+    }
+}
